use csv_core::{Reader, ReaderBuilder, ReadRecordResult, Terminator};

fn run(use_nfa: bool, chunks: &[&[u8]]) {
    let mut b = ReaderBuilder::new();
    b.terminator(Terminator::Any(b'|')).comment(Some(b'#')).nfa(use_nfa);
    let mut rdr: Reader = b.build();
    let mut out = [0u8; 64];
    let mut ends = [0usize; 8];
    println!("--- nfa={} ---", use_nfa);
    for (i, chunk) in chunks.iter().enumerate() {
        let mut inp: &[u8] = chunk;
        loop {
            let (res, nin, nout, nend) = rdr.read_record(inp, &mut out, &mut ends);
            println!("chunk{} res={:?} nin={} nout={} nend={} line={} ends={:?} data={:?}",
                i, res, nin, nout, nend, rdr.line(), &ends[..nend],
                String::from_utf8_lossy(&out[..nout]));
            inp = &inp[nin..];
            match res {
                ReadRecordResult::InputEmpty => break,
                _ => {}
            }
            if nin == 0 && !matches!(res, ReadRecordResult::Record) { break; }
        }
    }
    // flush
    loop {
        let (res, nin, nout, nend) = rdr.read_record(&[], &mut out, &mut ends);
        println!("flush res={:?} nin={} nout={} nend={} line={}", res, nin, nout, nend, rdr.line());
        if res == ReadRecordResult::End { break; }
    }
}

fn main() {
    let data: &[u8] = b"a\nb,1|# note\nc,2|";
    run(false, &[data]);
    run(true, &[data]);
    run(false, &[b"a", b"\nb", b",1|# note\nc", b",2|"]);
}
EOF
