fn read_records_chunked(rdr: &mut Reader, data: &[u8], chunk: usize) -> (Vec<Vec<Vec<u8>>>, u64) {
    use crate::ReadRecordResult::*;
    let mut records = vec![];
    let mut out = [0u8; 64];
    let mut ends = [0usize; 8];
    let (mut outpos, mut endpos) = (0, 0);
    let mut i = 0;
    let mut cur: Vec<Vec<u8>> = vec![];
    loop {
        let inp = if i < data.len() { &data[i..(i+chunk).min(data.len())] } else { &[][..] };
        let (res, nin, nout, nend) = rdr.read_record(inp, &mut out[outpos..], &mut ends[endpos..]);
        i += nin;
        outpos += nout;
        endpos += nend;
        match res {
            InputEmpty => { assert!(i >= data.len()); }
            OutputFull | OutputEndsFull => panic!("buffer too small"),
            Record => {
                let mut start = 0;
                for &e in &ends[..endpos] {
                    cur.push(out[start..e].to_vec());
                    start = e;
                }
                records.push(std::mem::take(&mut cur));
                outpos = 0; endpos = 0;
            }
            End => break,
        }
    }
    (records, rdr.line())
}
