fn stream_comma() {
    use crate::ReadFieldResult::*;

    let mut rdr = Reader::new();
    assert_read!(rdr, b(","), &mut [0], 1, 0, Field { record_end: false });
    assert_read!(rdr, &[], &mut [0], 0, 0, Field { record_end: true });
