parses_to!(
    comment_custom_terminator_with_escape,
    "\"a!\"b\",1|# !\"|\nc,2|",
    csv![["a\"b", "1"], ["c", "2"]],
    |b: &mut ReaderBuilder| {
        b.terminator(Terminator::Any(b'|'))
            .comment(Some(b'#'))
            .escape(Some(b'!'));
    }
);
